for (const language of languages) {
  const data = cropLocaleData[language];
  const keys = ['Top margin (mm)', 'Right margin (mm)', 'Bottom margin (mm)', 'Left margin (mm)', 'Margins apply to every page. Rotated pages must be set to 0° first.', 'Changing the CropBox hides content outside the page view; it does not securely delete it. Do not use this to conceal sensitive information.', 'Processing stays on this device. A computer is recommended for large PDFs. Limits: 100 MB and 300 pages; actual performance depends on available memory.', 'Crop PDF', 'Cropping PDF pages on your device…', 'Choose a PDF of 100 MB or less.', 'Enter margins from 0 to 500 mm.', 'Rotate pages to 0° before cropping this PDF.', 'The margins are too large for at least one page.', 'This PDF could not be cropped.', 'Cropped PDF copy is ready. The original is unchanged; content outside the CropBox may still be present.'];
  keys.forEach((key, index) => { ui[language][key] = data.ui[index]; });
  copy[language]['pdf-crop'] = data.copy;
}

export const pdfParityLocales = Object.fromEntries(languages.map((language) => [language, {
  ui: ui[language],
  copy: copy[language],
} ]));
